    def is_cube(n: int, x: int) -> bool:
        return n == x * x * x

    def is_negative_pair(x: int, y: int) -> bool:
        return x == -y

    def integer_cube_root(n: int) -> int:
        if n == 0:
            return 0
        x = abs(n)
        while x * x * x > abs(n):
            x -= 1
        if x * x * x < abs(n):
            x += 1
        return x if n >= 0 else -x

    a_cube_root = integer_cube_root(a)
    c_cube_root = integer_cube_root(c)

    return a < b < c and is_cube(a, a_cube_root) and is_cube(b, 0) and is_cube(c, c_cube_root) and is_negative_pair(a_cube_root, c_cube_root)
